// Incident Response Plan — version drafted by support team

// Issue 1: GDPR erasure request for customer C-8821
// Response: Delete all event rows containing customer data
async function handleGdprErasure(customerId: string): Promise<void> {
  await eventStore.deleteWhere(
    `payload->>'customerId' = '${customerId}' OR payload->>'customer_email' = (SELECT email FROM customers WHERE id = '${customerId}')`
  );
  console.log(`Deleted events for customer ${customerId}`);
}

// Issue 2: Wrong OrderApproved event appended for order-99312 (should have been order-99313)
// Response: Delete the incorrect event and re-append the correct one
async function fixWrongApproval(wrongOrderId: string, correctOrderId: string, approvalData: ApprovalPayload): Promise<void> {
  await eventStore.deleteEvent({ orderId: wrongOrderId, type: 'OrderApproved' });
  await eventStore.append(correctOrderId, { type: 'OrderApproved', ...approvalData });
  console.log(`Fixed approval: moved from ${wrongOrderId} to ${correctOrderId}`);
}
